                      className: (isCur
                        ? (isContrast ? 'bg-yellow-300 text-black border-2 border-yellow-300 font-bold' : 'bg-violet-600 text-white font-bold')
                        : btnSecondary) + ' px-2.5 py-1 rounded-full text-xs',
